package com.citacloud.app.services; import com.citacloud.app.models.*; import com.citacloud.app.repositories.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.*;
@Service public class HistorialClinicoService {private final HistorialClinicoRepository historias;private final PacienteRepository pacientes;public HistorialClinicoService(HistorialClinicoRepository h,PacienteRepository p){historias=h;pacientes=p;}public List<HistorialClinico> listar(UUID e){return historias.findByEmpresaIdOrderByActualizadoEnDesc(e);}@Transactional public HistorialClinico guardar(UUID e,UUID pacienteId,String resumen,String alergias,String antecedentes){Paciente p=pacientes.findByIdAndEmpresaId(pacienteId,e).orElseThrow(()->new IllegalArgumentException("Paciente no encontrado para esta empresa."));HistorialClinico h=historias.findByEmpresaIdAndPacienteId(e,pacienteId).orElseGet(HistorialClinico::new);h.setEmpresaId(e);h.setPaciente(p);h.setResumen(limpiar(resumen));h.setAlergias(limpiar(alergias));h.setAntecedentes(limpiar(antecedentes));h.setActualizadoEn(LocalDateTime.now());return historias.save(h);}private String limpiar(String s){return s==null?null:s.trim();}}
